                        last_cat="",
                        last_sub="",
                        cat_no=0,
                        sub_no=0,
                        item_no=0,
                        total_price=0,
                        total_work=0
                    ) %}



                    <!-- =================================================
                         BOQ TABLE
                         ================================================= -->

                    <table class="boq-table">


                        <colgroup>

                            <col style="width:5%;">

                            <col style="width:35%;">

                            <col style="width:8%;">

                            <col style="width:6%;">

                            <col style="width:12%;">

                            <col style="width:12%;">

                            <col style="width:8%;">

                            <col style="width:14%;">

                        </colgroup>



                        <thead>


                            <tr>


                                <th>
                                    No.
                                </th>


                                <th>
                                    Item Description
                                </th>


                                <th>
                                    Quantity
                                </th>


                                <th>
                                    Unit
                                </th>


                                <th>
                                    Unit Rate
                                </th>


                                <th>
                                    Price
                                </th>


                                <th>
                                    Progress %
                                </th>


                                <th>
                                    Value
                                </th>


                            </tr>


                        </thead>



                        <tbody>


                            {% for row in doc.items or [] %}


                                {% set cat_label =
                                    frappe.db.get_value(
                                        "BOQ Category",
                                        row.category_name,
                                        "category_name"
                                    )
                                    or row.category_name
                                    or "Uncategorized"
                                %}


                                {% set sub_label =
                                    frappe.db.get_value(
                                        "BOQ Category",
                                        row.sub_category,
                                        "category_name"
                                    )
                                    or row.sub_category
                                    or ""
                                %}


                                {% set item_label =
                                    frappe.db.get_value(
                                        "BOQ Item",
                                        row.boq_item,
                                        "item_name"
                                    )
                                    if row.boq_item
                                    else ""
                                %}


                                {% set price =
                                    (row.boq_qty or 0)
                                    *
                                    (row.boq_rate or 0)
                                %}


                                {% set work_value =
                                    row.current_amount or 0
                                %}


                                {% set ns.total_price =
                                    ns.total_price + price
                                %}


                                {% set ns.total_work =
                                    ns.total_work + work_value
                                %}



                                <!-- =====================================
                                     MAIN CATEGORY
                                     ===================================== -->

                                {% if row.category_name != ns.last_cat %}


                                    {% set ns.cat_no =
                                        ns.cat_no + 1
                                    %}


                                    {% set ns.sub_no = 0 %}

                                    {% set ns.item_no = 0 %}

                                    {% set ns.last_cat =
                                        row.category_name
                                    %}

                                    {% set ns.last_sub = "" %}


                                    <tr class="main-cat-row">


                                        <td class="c">

                                            {{ ns.cat_no }}

                                        </td>


                                        <td colspan="7">

                                            {{ cat_label }}

                                        </td>


                                    </tr>


                                {% endif %}



                                <!-- =====================================
                                     SUB CATEGORY
                                     ===================================== -->

                                {% if row.sub_category
                                    and row.sub_category != ns.last_sub
                                %}


                                    {% set ns.sub_no =
                                        ns.sub_no + 1
                                    %}


                                    {% set ns.item_no = 0 %}


                                    {% set ns.last_sub =
                                        row.sub_category
                                    %}


                                    <tr class="sub-cat-row">


                                        <td class="c">

                                            {{ ns.cat_no }}.{{ ns.sub_no }}

                                        </td>


                                        <td colspan="7">

                                            {{ sub_label }}

                                        </td>


                                    </tr>


                                {% endif %}



                                <!-- =====================================
                                     ITEM
                                     ===================================== -->

                                {% set ns.item_no =
                                    ns.item_no + 1
                                %}


                                <tr>


                                    <td class="c">

                                        {{
                                            letters[ns.item_no - 1]
                                            if ns.item_no <= 26
                                            else ns.item_no
                                        }}

                                    </td>


                                    <td>

                                        {{ item_label or row.boq_item or "" }}

                                    </td>


                                    <td class="r">

                                        {{
                                            "{:,.2f}".format(
                                                row.boq_qty or 0
                                            )
                                            .rstrip("0")
                                            .rstrip(".")
                                        }}

                                    </td>


                                    <td class="c">

                                        {{ row.uom or "" }}

                                    </td>


                                    <td class="r">

                                        {{ frappe.utils.fmt_money(
                                            row.boq_rate or 0,
                                            currency=currency
                                        ) }}

                                    </td>


                                    <td class="r">

                                        {{ frappe.utils.fmt_money(
                                            price,
                                            currency=currency
                                        ) }}

                                    </td>


                                    <td class="c">

                                        {{
                                            "{:,.2f}".format(
                                                row.work_percent or 0
                                            )
                                            .rstrip("0")
                                            .rstrip(".")
                                        }}%

                                    </td>


                                    <td class="r bold">

                                        {{ frappe.utils.fmt_money(
                                            work_value,
                                            currency=currency
                                        ) }}

                                    </td>


                                </tr>


                            {% endfor %}


                        </tbody>



                        <!-- =============================================
                             TOTAL
                             ============================================= -->

                        <tfoot>


                            <tr>


                                <td colspan="5">


                                    Total - Billing

                                </td>


                                <td class="r">

                                    {{ frappe.utils.fmt_money(
                                        ns.total_price,
                                        currency=currency
                                    ) }}

                                </td>


                                <td></td>


                                <td class="r">

                                    {{ frappe.utils.fmt_money(
                                        ns.total_work,
                                        currency=currency
                                    ) }}

                                </td>


                            </tr>


                        </tfoot>


                    </table>
                    
                    <!-- ============================================================
                         AUTHORIZED SIGNATURE
                         ============================================================ -->
                    
                    <div class="ra-signature-block">
                    
                        <div class="ra-signature-company">
                            For Vivira Infra Project
                        </div>
                    
                        <div class="ra-signature-space">
                            &nbsp;
                        </div>
                    
                        <div class="ra-signature-label">
                            Authorized Signature
                        </div>
                    
                    </div>


                </div>


            </td>

        </tr>

    </tbody>


</table>"}]
